import {recommendLanguage,browserLanguage,LANGUAGES} from './language-preference.fb9e79ff764d.js';
const script=[...document.scripts].find(s=>s.dataset.game&&s.dataset.language&&s.dataset.base);const current=script?.dataset.language||'ko',base=script?.dataset.base,game=script?.dataset.game;if(base&&game)init();
async function init(){const names={ko:'한국어',en:'English',zh:'简体中文',es:'Español',ja:'日本語',de:'Deutsch',fr:'Français',pt:'Português'},copy={ko:{title:'추천 언어',action:'이 언어로 보기',saved:'저장한 언어',note:'국가 기반 추천입니다. 언제든 위에서 언어를 바꿀 수 있어요.',privacy:'IP 국가 조회: GeoJS · IP 주소는 저장하지 않습니다.'},en:{title:'Suggested language',action:'Use this language',saved:'Your saved language',note:'Suggested by country. You can switch languages above anytime.',privacy:'IP country lookup: GeoJS · We do not store IP addresses.'},zh:{title:'推荐语言',action:'使用此语言',saved:'已保存的语言',note:'根据国家推荐。你可以随时在上方切换语言。',privacy:'IP 国家查询：GeoJS · 本站不存储 IP 地址。'},es:{title:'Idioma recomendado',action:'Usar este idioma',saved:'Tu idioma guardado',note:'Recomendado según el país. Puedes cambiarlo arriba.',privacy:'País por IP: GeoJS · No guardamos direcciones IP.'},ja:{title:'おすすめの言語',action:'この言語で表示',saved:'保存した言語',note:'国に基づく提案です。上でいつでも変更できます。',privacy:'IPによる国の照会: GeoJS · IPアドレスは保存しません。'},de:{title:'Empfohlene Sprache',action:'Diese Sprache verwenden',saved:'Gespeicherte Sprache',note:'Vorschlag anhand des Landes. Die Sprache kann oben jederzeit geändert werden.',privacy:'Länderabfrage per IP: GeoJS · Wir speichern keine IP-Adressen.'},fr:{title:'Langue suggérée',action:'Utiliser cette langue',saved:'Langue enregistrée',note:'Suggestion selon le pays. Vous pouvez changer de langue en haut à tout moment.',privacy:'Pays par adresse IP : GeoJS · Nous ne conservons pas les adresses IP.'},pt:{title:'Idioma sugerido',action:'Usar este idioma',saved:'Idioma guardado',note:'Sugestão com base no país. Pode mudar o idioma acima a qualquer momento.',privacy:'Consulta do país por IP: GeoJS · Não guardamos endereços IP.'}}[current];
const key=game+'-language';let storage,saved;try{storage=localStorage;saved=storage.getItem(key);}catch{}document.querySelectorAll('[data-language]').forEach(a=>a.addEventListener('click',()=>{try{storage?.setItem(key,a.dataset.language);}catch{}}));
let suggested=LANGUAGES.includes(saved)?saved:browserLanguage(navigator.languages||[navigator.language]),country='';if(!saved){try{const cache=JSON.parse(sessionStorage.getItem('nana-language-country')||'null');if(cache&&Date.now()-cache.time<3600000&&/^[A-Z]{2}$/.test(cache.country))country=cache.country;}catch{}if(!country){try{const response=await fetch('https://get.geojs.io/v1/ip/country.json',{credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(2200)});if(response.ok){const data=await response.json();if(/^[A-Z]{2}$/.test(data.country))country=data.country;try{if(country)sessionStorage.setItem('nana-language-country',JSON.stringify({country,time:Date.now()}));}catch{}}}catch{}}suggested=recommendLanguage(country,navigator.languages||[navigator.language]);}
const box=document.getElementById('language-suggestion');if(!box)return;box.hidden=false;const title=document.createElement('span');title.textContent=(saved?copy.saved:copy.title)+': '+names[suggested]+(country?' · '+country:'');box.append(title);if(suggested!==current){const a=document.createElement('a');a.href=document.querySelector('[data-language="'+suggested+'"]')?.href||new URL(suggested+'/',base).href;a.textContent=copy.action;a.onclick=()=>{try{storage?.setItem(key,suggested);}catch{}};box.append(a);}const note=document.createElement('small');note.textContent=copy.note;box.append(note);const privacy=document.createElement('small');privacy.textContent=copy.privacy;box.append(privacy);}
